'use strict';

/**
* Test whether a double-precision complex floating-point strided array contains at least `k` truthy elements.
*
* @module @stdlib/blas/ext/base/zsome
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var zsome = require( '@stdlib/blas/ext/base/zsome' );
*
* var x = new Complex128Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = zsome( x.length, 1, x, 1 );
* // returns true
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var zsome = require( '@stdlib/blas/ext/base/zsome' );
*
* var x = new Complex128Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = zsome.ndarray( x.length, 1, x, 1, 0 );
* // returns true
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var zsome;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zsome = main;
} else {
	zsome = tmp;
}


// EXPORTS //

module.exports = zsome;

// exports: { "ndarray": "zsome.ndarray" }
